import{_ as t,o as r,c as i,a2 as o}from"./chunks/framework.mrTIYZc5.js";const g=JSON.parse('{"title":"Security Model","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md"}'),a={name:"guide/security.md"};function n(s,e,c,l,h,d){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="security-model" tabindex="-1">Security Model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security Model&quot;">​</a></h1><p>DSO is designed for high-trust environments where secret persistence on peripheral storage is unacceptable. This document formalizes the DSO security architecture, threat model, and mitigation strategies.</p><hr><h2 id="_1-threat-model" tabindex="-1">1. Threat Model <a class="header-anchor" href="#_1-threat-model" aria-label="Permalink to &quot;1. Threat Model&quot;">​</a></h2><p>DSO identifies and mitigates three primary threat vectors in Docker-based infrastructure.</p><h3 id="threat-vector-a-static-secret-proliferation" tabindex="-1">Threat Vector A: Static Secret Proliferation <a class="header-anchor" href="#threat-vector-a-static-secret-proliferation" aria-label="Permalink to &quot;Threat Vector A: Static Secret Proliferation&quot;">​</a></h3><ul><li><strong>Actor</strong>: Rogue developer or compromised CI/CD pipeline.</li><li><strong>Action</strong>: Credentials committed to VCS (GitHub/GitLab) or stored in persistent <code>.env</code> files.</li><li><strong>DSO Mitigation</strong>: <strong>Zero-File Footprint</strong>. Secrets are fetched at runtime and held in RAM. No plaintext credentials ever exist on the developer&#39;s laptop or in the repository.</li></ul><h3 id="threat-vector-b-compromised-host-lateral-movement" tabindex="-1">Threat Vector B: Compromised Host / Lateral Movement <a class="header-anchor" href="#threat-vector-b-compromised-host-lateral-movement" aria-label="Permalink to &quot;Threat Vector B: Compromised Host / Lateral Movement&quot;">​</a></h3><ul><li><strong>Actor</strong>: Attacker with non-root access to the host OS.</li><li><strong>Action</strong>: Reading secrets from the host&#39;s filesystem, scanning <code>/proc</code>, or intercepting network traffic.</li><li><strong>DSO Mitigation</strong>: <ul><li><strong>Unix Socket Isolation</strong>: CLI-to-Agent communication is restricted to a secure Unix socket. No network ports are exposed.</li><li><strong>Memory-Only Store</strong>: Secrets never touch the physical disk (SSD/HDD).</li><li><strong>UID Separation</strong>: The DSO agent can be configured to run under a dedicated system user, isolating its memory space.</li></ul></li></ul><h3 id="threat-vector-c-secret-drift-stale-credentials" tabindex="-1">Threat Vector C: Secret Drift &amp; Stale Credentials <a class="header-anchor" href="#threat-vector-c-secret-drift-stale-credentials" aria-label="Permalink to &quot;Threat Vector C: Secret Drift &amp; Stale Credentials&quot;">​</a></h3><ul><li><strong>Actor</strong>: Phishing attacker or ex-employee.</li><li><strong>Action</strong>: Exploiting a recycled or &quot;leaked&quot; credential that is still active in a running container.</li><li><strong>DSO Mitigation</strong>: <strong>Continuous Reconciliation</strong>. The Watcher Engine ensures that secret rotations in the Vault are reflected in running containers within minutes/seconds, minimizing the &quot;Window of Vulnerability.&quot;</li></ul><hr><h2 id="_2-zero-persistence-guarantees" tabindex="-1">2. Zero-Persistence Guarantees <a class="header-anchor" href="#_2-zero-persistence-guarantees" aria-label="Permalink to &quot;2. Zero-Persistence Guarantees&quot;">​</a></h2><p>DSO&#39;s most critical security property is its commitment to <strong>Zero-Persistence</strong>.</p><h3 id="the-ramfs-tar-streaming-mechanism" tabindex="-1">The RAMfs / Tar Streaming Mechanism <a class="header-anchor" href="#the-ramfs-tar-streaming-mechanism" aria-label="Permalink to &quot;The RAMfs / Tar Streaming Mechanism&quot;">​</a></h3><p>DSO does not use traditional host-path mounts for secrets. Instead, it leverages a two-stage injection process:</p><ol><li><strong>Memory Capture</strong>: The agent fetches secrets and wraps them into a TAR archive in process memory.</li><li><strong>RAMfs Injection</strong>: DSO uses the <code>CopyToContainer</code> API to stream the TAR ball directly into a <code>tmpfs</code> volume inside the container.</li></ol><p><strong>Security Result</strong>: If the server loses power or the container is killed, the secrets vanish instantly. There is no forensic trace of the secret value on the physical storage media.</p><hr><h2 id="_3-boundary-protection-the-docker-socket" tabindex="-1">3. Boundary Protection: The Docker Socket <a class="header-anchor" href="#_3-boundary-protection-the-docker-socket" aria-label="Permalink to &quot;3. Boundary Protection: The Docker Socket&quot;">​</a></h2><p>DSO interacts with the Docker Engine via the authenticated Unix socket (<code>/var/run/docker.sock</code>).</p><ul><li><strong>Authenticated Access</strong>: DSO uses the official Docker SDK, ensuring all actions are logged by the Docker daemon&#39;s audit stream.</li><li><strong>Encryption</strong>: While Unix sockets are local, DSO&#39;s communication with external Vaults (AWS/Azure/Vault) is strictly over <strong>TLS 1.2+</strong>.</li><li><strong>No Sidecars</strong>: Unlike Kubernetes-based solutions that require a sidecar container (increasing the attack surface), DSO&#39;s agent-based model keeps the container internal environment clean and isolated.</li></ul><hr><h2 id="_4-least-privilege-identity" tabindex="-1">4. Least Privilege &amp; Identity <a class="header-anchor" href="#_4-least-privilege-identity" aria-label="Permalink to &quot;4. Least Privilege &amp; Identity&quot;">​</a></h2><p>DSO advocates for <strong>Machine Identity</strong> over <strong>Static Tokens</strong>.</p><ul><li><strong>IAM Instance Profiles</strong>: In AWS/Azure environments, DSO auto-detects the host&#39;s instance profile. This means no AWS Access Keys or Azure Client Secrets are stored on the machine.</li><li><strong>Vault AppRole</strong>: For HashiCorp Vault, we recommend using AppRole with response wrapping, ensuring that even a local attacker cannot easily &quot;sniff&quot; the initial authentication token.</li><li><strong>Granular Mappings</strong>: DSO only injects the specific keys mapped in <code>dso.yaml</code> into a container. A compromised container only has access to its own secrets, not the entire vault.</li></ul><hr><h2 id="_5-compliance-alignment" tabindex="-1">5. Compliance Alignment <a class="header-anchor" href="#_5-compliance-alignment" aria-label="Permalink to &quot;5. Compliance Alignment&quot;">​</a></h2><p>DSO&#39;s architecture is built to satisfy the most stringent requirements of:</p><ul><li><strong>SOC2 Type II</strong>: Control over secret access and detailed audit trails.</li><li><strong>PCI-DSS</strong>: Protecting cardholder data by eliminating static credentials.</li><li><strong>ISO 27001</strong>: Establishing a robust, identity-based access control system.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><strong><a href="/docs/guide/architecture.html">System Architecture</a></strong>: Deep dive into the internal components.</li><li><strong><a href="/docs/guide/production-readiness.html">Production Readiness</a></strong>: Best practices for secure deployment.</li><li><strong><a href="/docs/guide/design-principles.html">Design Principles</a></strong>: The core pillars of the project.</li></ul>',32)])])}const m=t(a,[["render",n]]);export{g as __pageData,m as default};
